import React, { useState } from 'react';
import './App.css';

type TreeNode = {
  id: string;
  label: string;
  locked?: boolean;
  children?: TreeNode[];
};

const TREE: TreeNode = {
  id: 'parent',
  label: 'Parent',
  children: [
    {
      id: 'child-1',
      label: 'Child 1',
      children: [
        { id: 'child-1-1', label: 'Child 1.1' },
        { id: 'child-1-2', label: 'Child 1.2' }
      ]
    },
    { id: 'child-2', label: 'Child 2' },
    { id: 'child-3', label: 'Child 3' },
    { id: 'child-4', label: 'Child 4', locked: true },
    { id: 'child-5', label: 'Child 5', locked: true }
  ]
};

// Only items with no children store a value. Every other checkbox is calculated from them.
const INITIAL_SELECTED: Record<string, boolean> = { 'child-5': true };

function leavesOf(node: TreeNode): TreeNode[] {
  return node.children ? node.children.flatMap((child) => leavesOf(child)) : [node];
}

const unlockedLeavesOf = (node: TreeNode) => leavesOf(node).filter((leaf) => !leaf.locked);

const UNLOCKED_LEAVES = unlockedLeavesOf(TREE);

export default function App() {
  const [selected, setSelected] = useState(INITIAL_SELECTED);

  function stateOf(node: TreeNode) {
    if (!node.children) {
      return { checked: !!selected[node.id], indeterminate: false };
    }
    // Locked items do not count, or the parent could never reach "all checked".
    const leaves = unlockedLeavesOf(node);
    const selectedCount = leaves.filter((leaf) => selected[leaf.id]).length;
    return {
      checked: selectedCount > 0 && selectedCount === leaves.length,
      indeterminate: selectedCount > 0 && selectedCount < leaves.length
    };
  }

  function toggle(node: TreeNode) {
    const value = !stateOf(node).checked;
    setSelected((prev) => {
      const next = { ...prev };
      for (const leaf of unlockedLeavesOf(node)) next[leaf.id] = value;
      return next;
    });
  }

  // A plain function, not a component, so a new render never replaces the inputs.
  function renderNode(node: TreeNode) {
    const { checked, indeterminate } = stateOf(node);
    return (
      <React.Fragment key={node.id}>
        <label className={node === TREE ? 'parent' : 'child'}>
          <input
            type="checkbox"
            data-id={node.id}
            checked={checked}
            disabled={node.locked}
            // indeterminate is a property of the element, so JSX has no attribute for it.
            ref={(element) => {
              if (element) element.indeterminate = indeterminate;
            }}
            onChange={() => toggle(node)}
          />
          <span>{node.label}</span>
        </label>
        {node.children && (
          <div className="children">{node.children.map((child) => renderNode(child))}</div>
        )}
      </React.Fragment>
    );
  }

  // Walking the tree keeps this order, whatever order the clicks came in.
  const selectedIds = UNLOCKED_LEAVES.filter((leaf) => selected[leaf.id]).map((leaf) => leaf.id);

  return (
    <main className="main">
      <section className="section">
        <h1>Nested Checkboxes</h1>

        <div className="panel">
          {renderNode(TREE)}

          <p className="selection-summary" aria-live="polite">
            {selectedIds.length} of {UNLOCKED_LEAVES.length} selected
          </p>
          <p className="selected-ids">{selectedIds.join(', ')}</p>
          <button type="button" className="reset-selection" onClick={() => setSelected(INITIAL_SELECTED)}>
            Reset selection
          </button>
        </div>
      </section>
    </main>
  );
}

